// 「虚拟临床研究」's eligibility engine: the four states and the algebra over them,
// the evidence check that voids a fabricated fact, the as-of replay, and the
// evaluation report that describes reference agreement separately from clinical accuracy.
//
// The case numbers in the titles are the plan's: AC-14/15/36 are §12, and
// C2-15…C2-20 are attachment C2's matching cases. They are in the titles on
// purpose — the acceptance table is generated by grepping for them.
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import YAML from "yaml";

import {
  SATISFIED, NOT_SATISFIED, UNKNOWN, PENDING_RECHECK, VCR_MATCHING_STATES,
  admissibleFacts, ambiguousCriterionLanguageKeys, applicabilityConfusion, assessSubject, blockingExclusionUnknowns,
  criterionConfusion, criterionFunnel, criterionLanguageKeys, decidedShare, eligibilityCounts, errorLayer, evaluateCriterion,
  evaluateRequirement, evidenceGaps, factsVisibleAt, frozenAsOf, interRaterAgreement, kleeneAnd, kleeneNot, kleeneOr,
  matchingEvaluationReport, patientMatchingMetrics,
  requiresLanguageJudgment, runMatchingEvaluation,
  storedExclusion, summarizeEligibility, verifyFactEvidence, settleFactEvidence, windowStart, withinWindow, VCR_FACT_VOID_REASONS,
} from "../src/vcrMatching.mjs";
import { clinicalFactView, validateCapabilityManifest } from "@evimed/domain";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const AS_OF = "2026-09-28T00:00:00Z";

/** A one-document chart with the spans computed from the text, the way the fixture generator does. */
function chart(text, id = "doc-1") {
  return {
    documents: { [id]: { id, text } },
    /** @param {string} surface @param {any} rest */
    fact(surface, rest = {}) {
      const start = text.indexOf(surface);
      assert.notEqual(start, -1, `fixture: ${surface} is not in the chart`);
      return {
        id: rest.id ?? `f-${start}`,
        polarity: "affirmed",
        extractedBy: "model",
        visibleAt: "2026-09-01T00:00:00Z",
        surface,
        ...rest,
        source: { documentId: id, start, end: start + surface.length, quote: surface },
      };
    },
  };
}

const CRITERION_MI = {
  id: "crt-mi", kind: "exclusion", criterionType: "time_window",
  sourceText: "近 6 个月内发生过心肌梗死者除外",
  requirement: { op: "absent", variable: "myocardial_infarction", window: { months: 6 } },
};

// --------------------------------------------------------------- C2-15

test("C2-15 AND, OR and NOT agree with Kleene's strong three-valued tables", () => {
  // AND
  assert.equal(kleeneAnd(SATISFIED, SATISFIED), SATISFIED);
  assert.equal(kleeneAnd(SATISFIED, NOT_SATISFIED), NOT_SATISFIED);
  assert.equal(kleeneAnd(SATISFIED, UNKNOWN), UNKNOWN);
  assert.equal(kleeneAnd(NOT_SATISFIED, NOT_SATISFIED), NOT_SATISFIED);
  assert.equal(kleeneAnd(NOT_SATISFIED, UNKNOWN), NOT_SATISFIED, "false absorbs unknown");
  assert.equal(kleeneAnd(UNKNOWN, UNKNOWN), UNKNOWN);
  // OR
  assert.equal(kleeneOr(SATISFIED, SATISFIED), SATISFIED);
  assert.equal(kleeneOr(SATISFIED, NOT_SATISFIED), SATISFIED);
  assert.equal(kleeneOr(SATISFIED, UNKNOWN), SATISFIED, "true absorbs unknown");
  assert.equal(kleeneOr(NOT_SATISFIED, NOT_SATISFIED), NOT_SATISFIED);
  assert.equal(kleeneOr(NOT_SATISFIED, UNKNOWN), UNKNOWN);
  assert.equal(kleeneOr(UNKNOWN, UNKNOWN), UNKNOWN);
  // NOT
  assert.equal(kleeneNot(SATISFIED), NOT_SATISFIED);
  assert.equal(kleeneNot(NOT_SATISFIED), SATISFIED);
  assert.equal(kleeneNot(UNKNOWN), UNKNOWN);
  // Commutative and associative, like the algebra they implement.
  for (const a of [SATISFIED, NOT_SATISFIED, UNKNOWN]) {
    for (const b of [SATISFIED, NOT_SATISFIED, UNKNOWN]) {
      assert.equal(kleeneAnd(a, b), kleeneAnd(b, a));
      assert.equal(kleeneOr(a, b), kleeneOr(b, a));
      for (const c of [SATISFIED, NOT_SATISFIED, UNKNOWN]) {
        assert.equal(kleeneAnd(kleeneAnd(a, b), c), kleeneAnd(a, kleeneAnd(b, c)));
        assert.equal(kleeneOr(kleeneOr(a, b), c), kleeneOr(a, kleeneOr(b, c)));
        // De Morgan holds in Kleene logic and is the cheapest proof the table is right.
        assert.equal(kleeneNot(kleeneAnd(a, b)), kleeneOr(kleeneNot(a), kleeneNot(b)));
      }
    }
  }
});

test("C2-15 a deferral behaves as unknown in the tables and survives only where the answer is indeterminate", () => {
  assert.equal(kleeneAnd(NOT_SATISFIED, PENDING_RECHECK), NOT_SATISFIED, "a definite no is not deferred");
  assert.equal(kleeneOr(SATISFIED, PENDING_RECHECK), SATISFIED, "a definite yes is not deferred");
  assert.equal(kleeneAnd(SATISFIED, PENDING_RECHECK), PENDING_RECHECK);
  assert.equal(kleeneOr(NOT_SATISFIED, PENDING_RECHECK), PENDING_RECHECK);
  assert.equal(kleeneNot(PENDING_RECHECK), PENDING_RECHECK);
  // And the thing the deferral exists to prevent: it is never rounded up.
  assert.notEqual(kleeneAnd(SATISFIED, PENDING_RECHECK), SATISFIED);
});

test("C2-15 AC-14 an unknown exclusion criterion never lets a subject read as eligible", () => {
  const judgments = [
    { criterionId: "a", kind: "inclusion", applicable: true, state: SATISFIED },
    { criterionId: "b", kind: "exclusion", applicable: true, state: UNKNOWN },
  ];
  assert.equal(summarizeEligibility(judgments), "insufficient_evidence");
  assert.deepEqual(blockingExclusionUnknowns(judgments), ["b"]);
  // Nor does it become a refusal: unknown is not "no".
  assert.notEqual(summarizeEligibility(judgments), "ineligible");
});

// --------------------------------------------------------------- C2-16

test("C2-16 AC-14 a missing treatment history leaves the washout unknown, never satisfied", () => {
  const washout = {
    id: "crt-washout", kind: "exclusion", criterionType: "prior_treatment",
    requirement: { op: "elapsed_since", variable: "docetaxel", days: 28, comparator: "gte" },
  };
  const bare = evaluateCriterion(washout, { facts: [], asOf: Date.parse(AS_OF) });
  assert.equal(bare.state, UNKNOWN);
  assert.notEqual(bare.state, SATISFIED);
  assert.notEqual(bare.state, NOT_SATISFIED);
  assert.deepEqual(bare.missing, [{ variable: "docetaxel", reason: "not_recorded" }]);

  // With the evidence, the same criterion is decided; deleting it puts it back.
  const source = chart("末次多西他赛：2026-01-10。");
  const fact = source.fact("末次多西他赛：2026-01-10", {
    variable: "docetaxel", surface: "末次多西他赛", dateSurface: "2026-01-10", occurredAt: "2026-01-10T00:00:00Z",
  });
  const withEvidence = evaluateCriterion(washout, { facts: [fact], asOf: Date.parse(AS_OF) });
  assert.equal(withEvidence.state, SATISFIED);
  assert.equal(evaluateCriterion(washout, { facts: [], asOf: Date.parse(AS_OF) }).state, UNKNOWN);
});

test("C2-16 AC-14 unknown is not folded into not-satisfied anywhere in the summary", () => {
  const onlyUnknown = [{ criterionId: "a", kind: "inclusion", applicable: true, state: UNKNOWN }];
  assert.equal(summarizeEligibility(onlyUnknown), "insufficient_evidence");
  const counts = eligibilityCounts([
    { applicable: true, state: SATISFIED }, { applicable: true, state: UNKNOWN },
    { applicable: true, state: PENDING_RECHECK }, { applicable: false, state: UNKNOWN },
  ]);
  assert.deepEqual(counts, { satisfied: 1, not_satisfied: 0, unknown: 1, pending_recheck: 1, notApplicable: 1, total: 4 });
});

test('latest lab ties cannot choose a passing or failing value by row order', () => {
  const criterion={id:'tie',kind:'inclusion',criterionType:'lab',requirement:{op:'compare',variable:'creatinine',comparator:'lte',value:1.5,unit:'mg/dL',aggregate:'latest'}};
  const a={id:'a',variable:'creatinine',value:1,unit:'mg/dL',polarity:'affirmed',occurredAt:'2026-01-01'};
  const b={...a,id:'b',value:2.4};
  for(const facts of [[a,b],[b,a]]) assert.equal(evaluateCriterion(criterion,{facts,asOf:Date.parse(AS_OF)}).state,UNKNOWN);
  assert.equal(evaluateCriterion(criterion,{facts:[a,{...b,value:88.4,unit:'µmol/L'}],asOf:Date.parse(AS_OF)}).state,SATISFIED);
});

test('current non-administration is not a lifetime denial of earlier exposure', () => {
  const criterion={id:'wash',kind:'exclusion',criterionType:'prior_treatment',requirement:{op:'elapsed_since',variable:'docetaxel',days:28,comparator:'gte'}};
  const context={schema:1,assertion:'negated',experiencer:'patient',temporality:'current',medication:{state:'planned',absenceScope:'current'}};
  const current={id:'no-current-dose',variable:'docetaxel',polarity:'negated',clinical:context};
  assert.equal(evaluateCriterion(criterion,{facts:[current],asOf:Date.parse(AS_OF)}).state,UNKNOWN);
  const never={...current,provenance:{factSchema:1},clinical:{...context,temporality:'historical',medication:{state:'unknown',absenceScope:'never'}}};
  assert.equal(evaluateCriterion(criterion,{facts:[never],asOf:Date.parse(AS_OF)}).state,SATISFIED);
  assert.equal(evaluateCriterion(criterion,{facts:[{...never,occurredAt:'2026-09-27'}],asOf:Date.parse(AS_OF)}).state,UNKNOWN);
  assert.equal(evaluateCriterion(criterion,{facts:[{...never,occurredAt:AS_OF}],asOf:Date.parse(AS_OF)}).state,SATISFIED);
});

test("AC-14 not-applicable is a field beside the state, not a fifth state and not an unknown", () => {
  const pregnancy = {
    id: "crt-preg", kind: "exclusion", criterionType: "pregnancy",
    requirement: { op: "absent", variable: "pregnancy" },
    applicability: { op: "compare", variable: "sex", comparator: "in", value: ["female"] },
  };
  const male = [{ id: "s", variable: "sex", value: "male", polarity: "affirmed", extractedBy: "structured" }];
  const judged = evaluateCriterion(pregnancy, { facts: male, asOf: Date.parse(AS_OF) });
  assert.equal(judged.applicable, false);
  assert.equal(judged.applicabilityState, NOT_SATISFIED);
  assert.ok(VCR_MATCHING_STATES.includes(judged.state), "the state stays one of the four");
  // And a criterion that does not apply cannot hold a subject out of 「符合」.
  assert.equal(summarizeEligibility([
    { criterionId: "ok", kind: "inclusion", applicable: true, state: SATISFIED }, judged,
  ]), "eligible");
  // Nor does it raise an evidence gap: nobody should be sent to look for it.
  assert.deepEqual(evidenceGaps([judged]), []);
});

test("a failed conditional exclusion stays unknown until its applicability is established", () => {
  const criterion = {
    id: "conditional", kind: "exclusion",
    applicability: { op: "compare", variable: "subtype", comparator: "in", value: ["active"] },
    requirement: storedExclusion({ op: "present", variable: "recent_infection" }),
  };
  const unconditional = { ...criterion, id: "unconditional", applicability: null };
  const subtype = { id: "subtype", variable: "subtype", value: "active", extractedBy: "structured" };
  const infection = { id: "infection", variable: "recent_infection", polarity: "affirmed", extractedBy: "structured" };
  const evaluate = (facts, criteria = [criterion]) => assessSubject({ subjectKey: "P", asOf: AS_OF, criteria, facts });
  const unresolved = evaluate([infection]);
  const judgment = unresolved.judgments[0];
  assert.equal(judgment.state, UNKNOWN);
  assert.equal(judgment.applicabilityState, UNKNOWN);
  assert.equal(judgment.requirementState, NOT_SATISFIED);
  assert.equal(judgment.applicable, true);
  assert.equal(judgment.evidence[0].factId, "infection");
  assert.deepEqual(judgment.applicabilityMissing, [{ variable: "subtype", reason: "not_measured" }]);
  assert.deepEqual(unresolved.evidenceGaps, [{ variable: "subtype", reason: "not_measured", criterionIds: ["conditional"] }]);
  assert.equal(unresolved.summary, "insufficient_evidence");
  assert.deepEqual(decidedShare(unresolved.counts), { decided: 0, applicable: 1, percent: 0 });
  assert.deepEqual(unresolved.blockingExclusionUnknowns, ["conditional"]);
  assert.equal(criterionFunnel([unresolved])[0].not_satisfied, 0);

  const applicable = evaluate([infection, subtype]);
  assert.equal(applicable.summary, "ineligible");
  assert.equal(applicable.judgments[0].applicabilityEvidence[0].factId, "subtype");
  const inapplicable = evaluate([infection, { ...subtype, value: "resolved" }]);
  assert.equal(inapplicable.counts.notApplicable, 1);
  assert.equal(inapplicable.judgments[0].requirementState, NOT_SATISFIED);
  assert.equal(evaluate([infection], [criterion, unconditional]).summary, "ineligible", "another definite failure still decides");

  const clear = evaluate([{ ...infection, polarity: "negated" }]);
  assert.equal(clear.summary, "eligible", "the requirement holds whenever the premise applies");
  assert.equal(clear.judgments[0].requirementState, SATISFIED);
  assert.equal(clear.judgments[0].applicabilityState, UNKNOWN);
  assert.deepEqual(clear.evidenceGaps, unresolved.evidenceGaps);
  const deferred = evaluate([infection, { id: "treatment", variable: "treatment", occurredAt: "2026-09-20", extractedBy: "structured" }],
    [{ ...criterion, applicability: { op: "elapsed_since", variable: "treatment", days: 28 } }]);
  assert.equal(deferred.summary, "insufficient_evidence");
  assert.equal(deferred.judgments[0].applicabilityState, PENDING_RECHECK);
  assert.equal(deferred.judgments[0].applicabilityRecheckAt, "2026-10-18T00:00:00.000Z");
});

test("language answers for applicability and the requirement are separately anchored and cannot share a key", () => {
  const criterion = {
    id: "conditional", kind: "exclusion",
    applicability: { op: "language", key: "premise", text: "Does the subtype require screening?" },
    requirement: storedExclusion({ op: "language", key: "condition", text: "Is an infection present?" }),
  };
  const text = "Subtype is active. Infection is present.";
  const source = chart(text);
  const answer = quote => ({ state: SATISFIED, evidence: [{ documentId: "doc-1", quote, start: text.indexOf(quote), end: text.indexOf(quote) + quote.length }] });
  const modelJudgments = { premise: answer("Subtype is active."), condition: answer("Infection is present.") };
  const evaluate = (answers, selected = criterion) => assessSubject({
    subjectKey: "P", asOf: AS_OF, criteria: [selected], facts: [], documents: source.documents, modelJudgments: answers,
  });
  assert.deepEqual(criterionLanguageKeys(criterion), ["premise", "condition"]);
  const positive = evaluate(modelJudgments);
  assert.equal(positive.summary, "ineligible");
  assert.equal(positive.judgments[0].applicabilityEvidence[0].quote, "Subtype is active.");
  assert.equal(positive.judgments[0].evidence[0].quote, "Infection is present.");
  const negative = evaluate({ ...modelJudgments, premise: { ...modelJudgments.premise, state: NOT_SATISFIED } });
  assert.equal(negative.counts.notApplicable, 1);
  assert.equal(evaluate({ ...modelJudgments, premise: answer("Unsupported") }).summary, "insufficient_evidence");
  const ambiguous = { ...criterion, applicability: { ...criterion.applicability, key: "condition" } };
  assert.deepEqual(criterionLanguageKeys(ambiguous), []);
  const legacy = evaluate(modelJudgments, ambiguous);
  assert.equal(legacy.summary, "insufficient_evidence");
  assert.equal(legacy.judgments[0].applicabilityState, UNKNOWN);
  assert.equal(legacy.judgments[0].requirementState, UNKNOWN);
  assert.equal(legacy.judgments[0].applicabilityMissing[0].reason, "criterion_malformed");
});

test("a shared legacy answer cannot establish a different criterion's applicability", () => {
  const key = "shared";
  const question = { op: "language", key, text: "Has the patient had a transplant?" };
  const first = { id: "a", kind: "inclusion", requirement: question };
  const second = { id: "b", kind: "inclusion", requirement: { op: "absent", variable: "infection" },
    applicability: { op: "language", key, text: "Does the patient have HIV?" } };
  const text = "Kidney transplant performed.";
  const modelJudgments = { [key]: { state: SATISFIED, evidence: [{ documentId: "doc", quote: text, start: 0, end: text.length }] } };
  const facts = [{ id: "infection", variable: "infection", polarity: "affirmed", extractedBy: "structured" }];
  const evaluate = criteria => assessSubject({ subjectKey: "P", asOf: AS_OF, criteria, facts, documents: { doc: { text } }, modelJudgments });
  assert.deepEqual([...ambiguousCriterionLanguageKeys([first, second])], [key]);
  const legacy = evaluate([first, second]);
  assert.equal(legacy.summary, "insufficient_evidence");
  assert.equal(legacy.judgments[0].requirementState, UNKNOWN);
  assert.equal(legacy.judgments[1].applicabilityState, UNKNOWN);
  assert.equal(legacy.judgments[1].requirementState, NOT_SATISFIED);
  assert.deepEqual(legacy.judgments[1].applicabilityEvidence, []);

  const sameQuestion = { ...second, applicability: question };
  assert.deepEqual([...ambiguousCriterionLanguageKeys([first, sameQuestion])], []);
  assert.equal(evaluate([first, sameQuestion]).summary, "ineligible");
  assert.deepEqual([...ambiguousCriterionLanguageKeys([first, { ...second, applicability: { op: "language", key } }])], [key]);
});

// --------------------------------------------------------------- C2-17

test("C2-17 a value the source text does not contain voids the fact and the criterion reads unknown", () => {
  const source = chart("2026-09-06 血肌酐 2.4 mg/dL。");
  const fabricated = source.fact("血肌酐 2.4 mg/dL", {
    id: "f-creat", variable: "creatinine", value: 1.2, unit: "mg/dL",
    surface: "血肌酐", occurredAt: "2026-09-06T00:00:00Z",
  });
  assert.deepEqual(verifyFactEvidence(fabricated, { documents: source.documents, asOf: Date.parse(AS_OF) }),
    { ok: false, reason: "value_not_in_span" });

  const criterion = {
    id: "crt-creat", kind: "inclusion", criterionType: "lab",
    requirement: { op: "compare", variable: "creatinine", comparator: "lte", value: 1.5, unit: "mg/dL" },
  };
  const { facts, voided } = admissibleFacts([fabricated], { documents: source.documents, asOf: Date.parse(AS_OF) });
  assert.deepEqual(facts, []);
  assert.deepEqual(voided, [{ factId: "f-creat", variable: "creatinine", reason: "value_not_in_span" }]);
  assert.equal(evaluateCriterion(criterion, { facts, asOf: Date.parse(AS_OF) }).state, UNKNOWN);

  // The honest extraction of the same span passes and decides the criterion.
  const honest = { ...fabricated, value: 2.4 };
  assert.equal(verifyFactEvidence(honest, { documents: source.documents, asOf: Date.parse(AS_OF) }).ok, true);
  assert.equal(evaluateCriterion(criterion, { facts: [honest], asOf: Date.parse(AS_OF) }).state, NOT_SATISFIED);
});

test("C2-17 every other way a locator can lie is named, and none of them reads as satisfied", () => {
  const source = chart("否认心梗史，否认妊娠。");
  const good = source.fact("否认心梗史", { variable: "myocardial_infarction", polarity: "negated" });
  const context = { documents: source.documents, asOf: Date.parse(AS_OF) };
  assert.equal(verifyFactEvidence(good, context).ok, true);

  const cases = [
    ["locator_missing", { ...good, source: undefined }],
    ["document_unavailable", { ...good, source: { ...good.source, documentId: "doc-9" } }],
    ["span_out_of_range", { ...good, source: { ...good.source, end: 9_999 } }],
    ["quote_mismatch", { ...good, source: { ...good.source, quote: "确诊心梗" } }],
    ["surface_missing", { ...good, surface: undefined, surfaceForms: [] }],
    ["value_not_in_span", { ...good, surface: "否认糖尿病史" }],
    ["date_not_in_span", { ...good, dateSurface: "2026-01-01" }],
    ["not_yet_visible", { ...good, visibleAt: "2026-10-01T00:00:00Z" }],
    ["polarity_not_assertive", { ...good, polarity: "family" }],
  ];
  for (const [reason, fact] of cases) {
    assert.deepEqual(verifyFactEvidence(fact, context), { ok: false, reason }, reason);
    const judged = evaluateCriterion(CRITERION_MI, {
      facts: admissibleFacts([fact], context).facts, asOf: Date.parse(AS_OF),
    });
    assert.equal(judged.state, UNKNOWN, `${reason} must not decide the criterion`);
  }
});

// --------------------------------------------------------------- C2-18

test("C2-18 AC-15 a result that became visible after the assessment date is not in the replay", () => {
  const source = chart("2026-09-26 血肌酐 1.1 mg/dL。");
  const late = source.fact("血肌酐 1.1 mg/dL", {
    id: "f-late", variable: "creatinine", value: 1.1, unit: "mg/dL", surface: "血肌酐",
    occurredAt: "2026-09-26T00:00:00Z", recordedAt: "2026-09-27T00:00:00Z", visibleAt: "2026-09-30T00:00:00Z",
  });
  const criterion = {
    id: "crt-creat", kind: "inclusion", criterionType: "lab",
    requirement: { op: "compare", variable: "creatinine", comparator: "lte", value: 1.5, unit: "mg/dL" },
  };
  const replay = assessSubject({ subjectKey: "S", criteria: [criterion], facts: [late], documents: source.documents, asOf: AS_OF });
  assert.equal(replay.judgments[0].state, UNKNOWN, "it was not knowable on 2026-09-28");
  assert.equal(replay.factsWithheldAsFuture, 1);
  assert.deepEqual(factsVisibleAt([late], AS_OF), []);

  const later = assessSubject({ subjectKey: "S", criteria: [criterion], facts: [late], documents: source.documents, asOf: "2026-10-02T00:00:00Z" });
  assert.equal(later.judgments[0].state, SATISFIED, "the same fact decides it once it is visible");
  assert.equal(later.factsWithheldAsFuture, 0);
});

test("C2-18 AC-15 the three clocks are distinct: occurred and recorded do not admit a fact on their own", () => {
  const source = chart("2026-09-01 血肌酐 1.1 mg/dL。");
  const fact = source.fact("血肌酐 1.1 mg/dL", {
    variable: "creatinine", value: 1.1, unit: "mg/dL", surface: "血肌酐",
    occurredAt: "2026-09-01T00:00:00Z", recordedAt: "2026-09-02T00:00:00Z", visibleAt: "2026-09-30T00:00:00Z",
  });
  assert.deepEqual(factsVisibleAt([fact], AS_OF), [], "occurring before as-of is not being visible before it");
});

// --------------------------------------------------------------- C2-19

test("C2-19 近 6 个月无心梗: unscoped denial and an old event stay unknown; an event inside the window fails absence", () => {
  const rows = [
    ["否认心梗史。", "否认心梗史", "negated", null, UNKNOWN],
    ["2026-06-28 因急性心梗入院。", "2026-06-28 因急性心梗入院", "affirmed", "2026-06-28T00:00:00Z", NOT_SATISFIED],
    ["2026-02-20 因急性心梗入院。", "2026-02-20 因急性心梗入院", "affirmed", "2026-02-20T00:00:00Z", UNKNOWN],
  ];
  for (const [text, surface, polarity, occurredAt, expected] of rows) {
    const source = chart(text);
    const fact = source.fact(surface, { variable: "myocardial_infarction", polarity, occurredAt });
    const judged = evaluateCriterion(CRITERION_MI, {
      facts: admissibleFacts([fact], { documents: source.documents, asOf: Date.parse(AS_OF) }).facts,
      asOf: Date.parse(AS_OF),
    });
    assert.equal(judged.state, expected, `${surface} → ${expected}`);
    assert.equal(judged.decidedBy, "code");
    if (expected !== UNKNOWN) assert.ok(judged.evidence.length >= 1, "a decided criterion cites the sentence it was decided from");
  }
  // And the fourth reading, which is the one the other three exist to contrast:
  // the chart says nothing about the heart at all.
  assert.equal(evaluateCriterion(CRITERION_MI, { facts: [], asOf: Date.parse(AS_OF) }).state, UNKNOWN);
  // An event nobody dated cannot be placed in or out of the window.
  const undatedSource = chart("既往心梗。");
  const undated = undatedSource.fact("既往心梗", { variable: "myocardial_infarction", occurredAt: null });
  assert.equal(evaluateCriterion(CRITERION_MI, { facts: [undated], asOf: Date.parse(AS_OF) }).state, UNKNOWN);
});

test("C2-19 the window boundary is a calendar month, not thirty days", () => {
  const anchor = Date.parse(AS_OF);
  assert.equal(new Date(windowStart({ months: 6 }, anchor)).toISOString(), "2026-03-28T00:00:00.000Z");
  assert.equal(new Date(windowStart({ days: 180 }, anchor)).toISOString(), "2026-04-01T00:00:00.000Z");
  assert.equal(windowStart({}, anchor), null, "a criterion with no window has no boundary");
  const inside = { occurredAt: "2026-04-01T00:00:00Z" };
  const outside = { occurredAt: "2026-03-01T00:00:00Z" };
  assert.equal(withinWindow(inside, { months: 6 }, anchor), true);
  assert.equal(withinWindow(outside, { months: 6 }, anchor), false);
  assert.equal(withinWindow({ occurredAt: null }, { months: 6 }, anchor), null);
  assert.equal(withinWindow(outside, null, anchor), true, "no window means every date qualifies");
});

