test("a criterion only language can decide is answered by the model, and only with an anchored quote", () => {
  const source = chart("患者本人可理解研究内容并签署知情同意。");
  const node = { op: "language", key: "crt-consent", text: "受试者能够理解研究内容并签署知情同意书" };
  assert.equal(requiresLanguageJudgment(node), true);
  assert.equal(requiresLanguageJudgment({ op: "all", operands: [node] }), true);
  assert.equal(requiresLanguageJudgment({ op: "present", variable: "x" }), false);

  const base = { facts: [], asOf: Date.parse(AS_OF), documents: source.documents, criterionId: "crt-consent" };
  const quote = "患者本人可理解研究内容并签署知情同意";
  const start = "患者本人可理解研究内容并签署知情同意。".indexOf(quote);
  const anchored = { state: SATISFIED, evidence: [{ documentId: "doc-1", start, end: start + quote.length, quote }] };
  assert.equal(evaluateRequirement(node, { ...base, modelJudgments: { "crt-consent": anchored } }).state, SATISFIED);
  // The same verdict with a quote the chart does not carry is refused.
  const invented = { state: SATISFIED, evidence: [{ documentId: "doc-1", start: 0, end: 4, quote: "无法理解" }] };
  assert.equal(evaluateRequirement(node, { ...base, modelJudgments: { "crt-consent": invented } }).state, UNKNOWN);
  assert.equal(evaluateRequirement(node, { ...base, modelJudgments: {} }).state, UNKNOWN);
  assert.equal(evaluateCriterion({ id: "crt-consent", requirement: node }, { ...base, modelJudgments: { "crt-consent": anchored } }).decidedBy, "model");
});

